// Signed-intent offline tests: digest, encoders, signers and their refusals (no network). The on-chain verifiers are tested in Foundry against vectors
// generated by scripts/gen-intent-vectors.ts / gen-pq-vectors.ts, which use the same functions.
import { readFileSync } from "node:fs";
import { p256 } from "@noble/curves/p256";
import { hashTypedData, hexToBytes, keccak256, recoverAddress, toHex, type Hex } from "viem";
import { privateKeyToAccount } from "viem/accounts";
import { describe, expect, it } from "vitest";
import {
  FORS_MAX_SIGNATURES,
  IntentError,
  OneTimeKeyReused,
  Scheme,
  SignatureBudgetExhausted,
  attestationDigest,
  attestationTypedData,
  attestedParams,
  attestedWitness,
  buildWebAuthnAssertion,
  KeyBoundElsewhere,
  StepBudgetExceeded,
  claimLeaf,
  sphincsKeygen,
  sphincsSign,
  sphincsSteps,
  ecdsaParams,
  forsIntentSigner,
  forsKeygen,
  forsVerify,
  fileUsageStore,
  grindSalt,
  hashIntentTypedData,
  intentContext,
  intentDigest,
  memoryUsageStore,
  multisigParams,
  multisigWitness,
  p256Keygen,
  p256Params,
  paramsBlobInitCode,
  sha256Hex,
  signEcdsaIntent,
  signP256Intent,
  webauthnParams,
  wotsIntentSigner,
  wotsIntentVerify,
  wotsKeygen,
  wotsSteps,
  wotsStepsOfHash,
  xmssIntentSigner,
  xmssKeygen,
  xmssVerify,
} from "../src/index.ts";
import { prng } from "./random.ts";

const sk = (l: string): Hex => keccak256(toHex(`t2 unit ${l}`));
const RULE_CONTRACT = "0x1111111111111111111111111111111111111111" as const;
const b = { chainId: 1338, ruleContract: RULE_CONTRACT, ruleId: 4, ruleEpoch: 7, triggerData: "0xdeadbeef00112233" as Hex };
const BIND = { chainId: 1338, ruleContract: RULE_CONTRACT, ruleId: 4 } as const;

describe("digest", () => {
  it("equals EIP-712 hashTypedData (so wallets sign the same bytes) and the committed vector", () => {
    expect(intentDigest(b)).toBe(hashIntentTypedData(b));
    const vec = JSON.parse(readFileSync(new URL("../../../contracts/test/fixtures/intent-vectors.json", import.meta.url), "utf8")) as { digest: Hex; context: Hex };
    expect(intentDigest(b)).toBe(vec.digest);
    expect(intentContext(b)).toBe(vec.context);
    const att = { ...b, statement: keccak256(toHex("fact")) };
    expect(attestationDigest(att)).toBe(hashTypedData(attestationTypedData(att)));
  });
  it("changes with every field", () => {
    const d = intentDigest(b);
    for (const v of [{ ...b, chainId: 1 }, { ...b, ruleContract: "0x2222222222222222222222222222222222222222" as const }, { ...b, ruleId: 5 }, { ...b, ruleEpoch: 8 }, { ...b, triggerData: "0xdeadbeef00112234" as Hex }]) expect(intentDigest(v)).not.toBe(d);
    expect(new Set([intentDigest(b), attestationDigest({ ...b, statement: sk("a") }), attestationDigest({ ...b, statement: sk("b") })]).size).toBe(3);
  });
});

describe("ECDSA, P-256 and WebAuthn signers", () => {
  it("ECDSA witness is r ++ s ++ v with v 27/28, low s, and recovers the signer", async () => {
    const a = privateKeyToAccount(sk("ecdsa"));
    const w = await signEcdsaIntent(a, b);
    expect(hexToBytes(w).length).toBe(65);
    expect([27, 28]).toContain(parseInt(w.slice(-2), 16));
    expect(await recoverAddress({ hash: intentDigest(b), signature: w })).toBe(a.address);
  });
  it("P-256 signatures verify and are low-s; the WebAuthn assertion is built the way the contract checks it", () => {
    const k = p256Keygen();
    const w = signP256Intent(k, b);
    const pub = hexToBytes(`0x04${k.x.slice(2)}${k.y.slice(2)}`);
    const sig = new p256.Signature(BigInt(`0x${w.slice(2, 66)}`), BigInt(`0x${w.slice(66, 130)}`));
    expect(p256.verify(sig, hexToBytes(intentDigest(b)), pub, { prehash: false, lowS: true })).toBe(true);
    const a = buildWebAuthnAssertion(k, intentDigest(b), { rpId: "x.example" });
    expect(a.clientDataJSON.slice(a.typeIndex, a.typeIndex + 21)).toBe('"type":"webauthn.get"');
    expect(a.clientDataJSON.slice(a.challengeIndex, a.challengeIndex + 13)).toBe('"challenge":"');
    expect(a.clientDataJSON).toContain(Buffer.from(hexToBytes(intentDigest(b))).toString("base64url"));
    const msg = sha256Hex(Buffer.concat([hexToBytes(a.authenticatorData), hexToBytes(sha256Hex(Buffer.from(a.clientDataJSON)))]));
    const sig2 = new p256.Signature(BigInt(`0x${a.signature.slice(2, 66)}`), BigInt(`0x${a.signature.slice(66, 130)}`));
    expect(p256.verify(sig2, hexToBytes(msg), pub, { prehash: false, lowS: true })).toBe(true);
    expect(webauthnParams({ ...k, rpId: "x.example", requireUV: true }).length).toBe(2 + 128 * 2);
    expect(() => webauthnParams(k)).toThrow(/rpId/); // a zero rpIdHash accepts any relying party: explicit opt-out only
    expect(webauthnParams({ ...k, allowAnyRp: true }).length).toBe(2 + 128 * 2);
  });
});

describe("encoders refuse bad configs", () => {
  const a = privateKeyToAccount(sk("a"));
  const c2 = privateKeyToAccount(sk("c"));
  it("multisig: threshold, bounds, duplicates, witness shape", () => {
    const k = p256Keygen();
    const signers = [{ scheme: Scheme.ECDSA, key: ecdsaParams(a.address) }, { scheme: Scheme.P256, key: p256Params(k) }];
    expect(() => multisigParams(0, signers)).toThrow(IntentError);
    expect(() => multisigParams(3, signers)).toThrow(IntentError);
    expect(() => multisigParams(1, [signers[0]!, signers[0]!])).toThrow(/duplicate/);
    expect(() => multisigParams(1, Array.from({ length: 17 }, (_, i) => ({ scheme: Scheme.ECDSA, key: ecdsaParams(privateKeyToAccount(sk(`k${i}`)).address) })))).toThrow(/at most 16/);
    expect(() => multisigParams(1, [{ scheme: Scheme.P256, key: "0x1234" }])).toThrow(/key must be/);
    expect(multisigParams(2, signers).length).toBe(2 + 2 * 2 + (1 + 20 + 1 + 64) * 2);
    expect(() => multisigWitness(2, [{ index: 0, sig: "0x00" }])).toThrow(/exactly 2/);
    expect(() => multisigWitness(2, [{ index: 1, sig: "0x00" }, { index: 1, sig: "0x01" }])).toThrow(/one signer slot/);
    // any input order, output sorted by index
    expect(multisigWitness(2, [{ index: 1, sig: "0xbb" }, { index: 0, sig: "0xaa" }])).toBe("0x020000" + "01" + "aa" + "01" + "0001" + "bb");
  });
  it("attested: k/n bounds and duplicate attestors", () => {
    const st = sk("st");
    expect(() => attestedParams(st, 0, [a.address])).toThrow(IntentError);
    expect(() => attestedParams(st, 2, [a.address])).toThrow(IntentError);
    expect(() => attestedParams(st, 1, [a.address, a.address])).toThrow(/duplicate/);
    expect(attestedParams(st, 2, [a.address, c2.address]).length).toBe(2 + (32 + 2 + 40) * 2);
    expect(() => attestedWitness(2, [{ index: 0, sig: "0x00" }])).toThrow(/exactly 2/);
  });
  it("params blob init code returns exactly the params", () => {
    expect(paramsBlobInitCode("0xaabbcc")).toBe("0x61000380600c6000396000f3aabbcc");
    expect(() => paramsBlobInitCode("0x")).toThrow(IntentError);
  });
});

describe("one-time keys: the signer refuses what must never happen", () => {
  it("claimLeaf: same digest again is fine and returns the same salt; another digest throws; a key serves one binding; a failing makeExtra consumes nothing", () => {
    const st = memoryUsageStore();
    const K1 = "0xaa" as Hex;
    expect(claimLeaf(st, K1, BIND, 3, "0xaa", "T", () => "salt1")).toBe("salt1");
    expect(claimLeaf(st, K1, BIND, 3, "0xaa", "T", () => "salt2")).toBe("salt1");
    expect(() => claimLeaf(st, K1, BIND, 3, "0xbb", "T")).toThrow(OneTimeKeyReused);
    expect(claimLeaf(st, K1, BIND, 4, "0xbb", "T")).toBe("");
    // the same key for another rule, rule contract or chain is refused (two bindings would reuse leaf 3)
    expect(() => claimLeaf(st, K1, { ...BIND, ruleId: 5 }, 3, "0xcc", "T")).toThrow(KeyBoundElsewhere);
    expect(() => claimLeaf(st, K1, { ...BIND, ruleContract: "0x2222222222222222222222222222222222222222" }, 9, "0xcc", "T")).toThrow(KeyBoundElsewhere);
    expect(() => claimLeaf(st, K1, { ...BIND, chainId: 1 }, 9, "0xcc", "T")).toThrow(KeyBoundElsewhere);
    // a throwing makeExtra (budget exceeded) leaves nothing behind: not even the binding latch
    const fresh = memoryUsageStore();
    expect(() => claimLeaf(fresh, "0xdd", BIND, 0, "0x01", "T", () => { throw new StepBudgetExceeded(600, 400, 10); })).toThrow(StepBudgetExceeded);
    expect(fresh.get("bound:0xdd")).toBeUndefined();
    expect(claimLeaf(fresh, "0xdd", { ...BIND, ruleId: 9 }, 0, "0x01", "T", () => "ok")).toBe("ok"); // still free to bind elsewhere
  });
  it("fileUsageStore survives a restart", async () => {
    const { mkdtempSync } = await import("node:fs");
    const { tmpdir } = await import("node:os");
    const p = `${mkdtempSync(`${tmpdir()}/t2-`)}/leaves.json`;
    claimLeaf(fileUsageStore(p), "0xee", BIND, 1, "0xaa", "T", () => "s");
    expect(() => claimLeaf(fileUsageStore(p), "0xee", BIND, 1, "0xbb", "T")).toThrow(OneTimeKeyReused);
  });
  it("WOTS+: signs and verifies at leaf = epoch - firstEpoch; the same digest again gives the same signature; another digest for the epoch throws", () => {
    const tree = wotsKeygen(sk("w1"), sk("w2"));
    const s = wotsIntentSigner({ tree, firstEpoch: 5, binding: BIND, store: memoryUsageStore(), budget: { maxSteps: 1000, maxTries: 16 } });
    const w = s.sign(b);
    expect(wotsIntentVerify(s.key, intentDigest(b), 7, w)).toBe(true);
    expect(s.sign(b)).toBe(w);
    expect(() => s.sign({ ...b, triggerData: "0x01" })).toThrow(OneTimeKeyReused);
    expect(wotsIntentVerify(s.key, intentDigest(b), 8, w)).toBe(false); // another leaf
    expect(wotsIntentVerify({ ...s.key, firstEpoch: 4 }, intentDigest(b), 7, w)).toBe(false);
    expect(() => s.signDigest(intentDigest(b), 4)).toThrow(/below firstEpoch/);
    expect(() => s.signDigest(intentDigest(b), 5 + 1024)).toThrow(/exhausted/);
    expect(() => wotsIntentSigner({ tree, firstEpoch: 0, binding: BIND, budget: { maxSteps: 400 } } as never)).toThrow(/store/);
    expect(() => wotsIntentSigner({ tree, firstEpoch: 0, binding: BIND, store: memoryUsageStore() } as never)).toThrow(/budget/);
    // bound to one (chain, rule contract, rule): another rule or rule contract is refused before anything is signed
    expect(() => s.sign({ ...b, ruleId: 5 })).toThrow(/bound to/);
    expect(() => s.sign({ ...b, ruleContract: "0x2222222222222222222222222222222222222222" })).toThrow(/bound to/);
    expect(s.key).toMatchObject({ chainId: 1338, ruleId: 4 });
  }, 60_000);
  it("M2: a signature over the step budget throws and consumes nothing (no leaf, no binding); the same leaf then signs within a budget", () => {
    const tree = wotsKeygen(sk("w3"), sk("w4"));
    const store = memoryUsageStore();
    const tight = wotsIntentSigner({ tree, firstEpoch: 0, binding: BIND, store, budget: { maxSteps: 150, maxTries: 50 } }); // impossible: the minimum is ~360
    expect(() => tight.sign({ ...b, ruleEpoch: 0 })).toThrow(StepBudgetExceeded);
    const ok = wotsIntentSigner({ tree, firstEpoch: 0, binding: BIND, store, budget: { maxSteps: 700, maxTries: 50 } });
    const w = ok.sign({ ...b, ruleEpoch: 0 });
    expect(wotsIntentVerify(ok.key, intentDigest({ ...b, ruleEpoch: 0 }), 0, w)).toBe(true);
  }, 60_000);
  it("FORS: the ninth signature and a second digest for an epoch are refused; every signature verifies", () => {
    const key = forsKeygen(sk("f1"), sk("f2"));
    const s = forsIntentSigner({ key, firstEpoch: 10, binding: BIND, store: memoryUsageStore() });
    for (let e = 10; e < 10 + FORS_MAX_SIGNATURES; e++) {
      const d = intentDigest({ ...b, ruleEpoch: e });
      const w = s.signDigest(d, e);
      expect(forsVerify(key.pk, key.pubSeed, d, w)).toBe(true);
    }
    expect(() => s.signDigest(intentDigest({ ...b, ruleEpoch: 18 }), 18)).toThrow(SignatureBudgetExhausted);
    expect(() => s.signDigest(keccak256("0x01"), 12)).toThrow(OneTimeKeyReused);
    expect(() => s.signDigest(keccak256("0x01"), 9)).toThrow(/below firstEpoch/);
    // tampering anywhere breaks it
    const d = intentDigest({ ...b, ruleEpoch: 10 });
    const w = s.signDigest(d, 10);
    for (const i of [0, 40, 100, 3000, 6943]) {
      const bytes = hexToBytes(w);
      bytes[i] = bytes[i]! ^ 1;
      expect(forsVerify(key.pk, key.pubSeed, d, toHex(bytes))).toBe(false);
    }
  }, 60_000);
  it("XMSS-style: signs at q = epoch - firstEpoch, verifies, refuses a second digest and an out-of-range leaf", () => {
    const tree = xmssKeygen(sk("x1"), sk("x2"), 3);
    const s = xmssIntentSigner({ tree, firstEpoch: 2, binding: BIND, store: memoryUsageStore(), budget: { maxSteps: 1000, maxTries: 8 } });
    const d = intentDigest({ ...b, ruleEpoch: 4 });
    const w = s.signDigest(d, 4);
    expect(xmssVerify(tree.root, tree.I, 3, 2, d, w)).toBe(true);
    expect(xmssVerify(tree.root, tree.I, 3, 3, d, w)).toBe(false);
    expect(xmssVerify(tree.root, tree.I, 4, 2, d, w)).toBe(false);
    expect(() => s.signDigest(keccak256("0x02"), 4)).toThrow(OneTimeKeyReused);
    expect(() => s.signDigest(d, 2 + 8)).toThrow(/exhausted/);
  }, 60_000);
});

describe("SPHINCS+-style signer budget", () => {
  it("grinds the randomiser to a step budget, refuses an impossible one without signing, and verifies", () => {
    const key = sphincsKeygen(sk("s1"), sk("s2"));
    const d = intentDigest(b);
    expect(() => sphincsSign(key, d, { maxSteps: 100, maxTries: 3 })).toThrow(StepBudgetExceeded);
    const sig = sphincsSign(key, d, { maxSteps: 560, maxTries: 60 });
    expect(sphincsSteps(key.pubSeed, key.root, d, sig)).toBeLessThanOrEqual(560);
  }, 240_000);
});

describe("salt grinding", () => {
  it("wotsStepsOfHash equals wotsSteps", () => {
    const r = prng(99);
    for (let i = 0; i < 500; i++) {
      const h = toHex(Uint8Array.from({ length: 32 }, () => Math.floor(r() * 256)));
      expect(wotsStepsOfHash(hexToBytes(h))).toBe(wotsSteps(h));
    }
    expect(wotsStepsOfHash(new Uint8Array(32))).toBe(wotsSteps(toHex(new Uint8Array(32))));
    expect(wotsStepsOfHash(new Uint8Array(32).fill(0xff))).toBe(wotsSteps(toHex(new Uint8Array(32).fill(0xff))));
  });
  it("grindSalt stops at the target and never returns worse than the first candidate", () => {
    const g = grindSalt((i) => toHex(i, { size: 32 }), (s) => keccak256(s), { maxTries: 20_000, targetSteps: 440 });
    expect(g.steps).toBeLessThanOrEqual(440);
    const first = wotsStepsOfHash(hexToBytes(keccak256(toHex(0, { size: 32 }))));
    expect(g.steps).toBeLessThanOrEqual(first);
    const none = grindSalt((i) => toHex(i, { size: 32 }), (s) => keccak256(s), { maxTries: 5, targetSteps: 0 });
    expect(none.tries).toBe(5);
  });
});
